b, _ := os.ReadFile("plate-drawing.svg")
s := string(b)
i := strings.Index(s, "<path")
fmt.Println(s[i : i+300])
// count straight segments by length
lens := map[string]int{}
for _, part := range strings.Split(s, "<path")[1:] {
	j := strings.Index(part, "d='")
	q := `'`
	if j < 0 {
		j = strings.Index(part, `d="`)
		q = `"`
	}
	if j < 0 {
		continue
	}
	d := part[j+3:]
	d = d[:strings.Index(d, q)]
	f := strings.Fields(strings.NewReplacer("M", " M ", "L", " L ", ",", " ").Replace(d))
	var px, py float64
	have := false
	for k := 0; k+2 < len(f); k++ {
		if f[k] == "M" || f[k] == "L" {
			x, e1 := strconv.ParseFloat(f[k+1], 64)
			y, e2 := strconv.ParseFloat(f[k+2], 64)
			if e1 != nil || e2 != nil {
				continue
			}
			if f[k] == "L" && have {
				l := math.Hypot(x-px, y-py)
				if l > 4 {
					lens[fmt.Sprintf("%.2f", l)]++
				}
			}
			px, py, have = x, y, true
		}
	}
}
fmt.Println(lens)
